#[cfg(test)]
mod tests {
    extern crate std;

    use std::println;

    use p3_field::PrimeCharacteristicRing;

    use crate::tower::TowerLevel;
    use crate::{
        BinaryField2, BinaryField4, BinaryField8, BinaryField16, BinaryField32, BinaryField64,
        BinaryField128, Gf2,
    };

    /// `v_0 = 1` and `v_i² + v_i = v_{i−1}`, checked in each level's own arithmetic.
    fn check_recurrence<F: TowerLevel>(count: usize) {
        assert_eq!(F::cantor_basis(0), F::ONE);
        for i in 1..count {
            let v = F::cantor_basis(i);
            assert_eq!(v.square() + v, F::cantor_basis(i - 1), "level bit {i}");
        }
    }

    /// `v_0, …, v_{2^k−1}` spans `GF(2^(2^k))`, so `v_i` fits in `2^⌈log2(i+1)⌉` bits, and
    /// every vector past `v_0` is the root of `x² + x = v_{i−1}` whose lowest bit is clear.
    fn check_nesting<F: TowerLevel>(count: usize)
    where
        F::Repr: Into<u128>,
    {
        for i in 0..count {
            let width = (i + 1).next_power_of_two();
            let repr: u128 = F::cantor_basis(i).to_repr().into();
            assert!(
                width >= 128 || repr < 1u128 << width,
                "v_{i} escapes GF(2^{width})"
            );
            assert_eq!(
                repr & 1,
                u128::from(i == 0),
                "v_{i} is not the even representation"
            );
        }
    }

    /// The first `count` vectors are linearly independent over `F_2`: reducing each against
    /// the pivots already found must never drive it to zero.
    fn check_independent<F: TowerLevel>(count: usize)
    where
        F::Repr: Into<u128>,
    {
        // `pivots[b]` holds a vector whose highest set bit is `b`, or zero if there is none.
        let mut pivots = [0u128; 128];
        for i in 0..count {
            let mut v: u128 = F::cantor_basis(i).to_repr().into();
            while v != 0 {
                let high = 127 - v.leading_zeros() as usize;
                if pivots[high] == 0 {
                    pivots[high] = v;
                    break;
                }
                v ^= pivots[high];
            }
            assert_ne!(v, 0, "v_{i} depends on the earlier vectors");
        }
    }

    #[test]
    fn recurrence_holds_at_every_level() {
        check_recurrence::<Gf2>(1);
        check_recurrence::<BinaryField2>(2);
        check_recurrence::<BinaryField4>(4);
        check_recurrence::<BinaryField8>(8);
        check_recurrence::<BinaryField16>(16);
        check_recurrence::<BinaryField32>(32);
        check_recurrence::<BinaryField64>(64);
        check_recurrence::<BinaryField128>(128);
    }

    #[test]
    fn basis_is_nested_and_independent() {
        check_nesting::<BinaryField128>(128);
        check_independent::<BinaryField128>(128);
    }

    /// The two smallest vectors are pinned: `v_0 = 1`, and `v_1` is the generator `X_0` of
    /// `GF(4)` over `GF(2)`, whose bit pattern is `0b10`.
    #[test]
    fn smallest_vectors_are_pinned() {
        assert_eq!(BinaryField128::cantor_basis(0).to_repr(), 1);
        assert_eq!(BinaryField128::cantor_basis(1).to_repr(), 2);
    }

    #[test]
    #[should_panic(expected = "index out of range")]
    fn out_of_range_index_panics() {
        let _ = BinaryField8::cantor_basis(8);
    }

    /// Regenerates `CANTOR_BASIS_128`. The map `x ↦ x² + x` is `F_2`-linear on
    /// `GF(2^128)` with kernel `{0, 1}`, so `v_i` is recovered by solving a 128×128 `F_2`
    /// system and taking the solution whose lowest bit is clear. Run with
    /// `cargo test -p p3-binary-field -- --ignored --nocapture regenerate_cantor_basis`
    /// and paste the printed table into `CANTOR_BASIS_128`.
    #[test]
    #[ignore]
    fn regenerate_cantor_basis() {
        // Column `b` of the Artin–Schreier matrix is `e_b² + e_b` for the bit-basis vector `e_b`.
        let columns: [u128; 128] = core::array::from_fn(|b| {
            let e = BinaryField128::from_repr(1u128 << b);
            (e.square() + e).to_repr()
        });

        let mut basis = [0u128; 128];
        basis[0] = 1;
        for i in 1..128 {
            basis[i] = solve_artin_schreier(&columns, basis[i - 1]);

            // Never print a table the recurrence does not satisfy.
            let v = BinaryField128::from_repr(basis[i]);
            assert_eq!(v.square() + v, BinaryField128::from_repr(basis[i - 1]));
            assert_eq!(basis[i] & 1, 0, "v_{i} is not the even representation");
        }

        for (i, v) in basis.iter().enumerate() {
            println!("    0x{v:032x}, // v_{i}");
        }
    }

    /// Solves `M x = target` over `F_2`, where `M` has the given columns, and returns the
    /// solution whose lowest bit is clear.
    ///
    /// Gauss-Jordan on the columns: `image[c]` is the partially reduced image of the unit
    /// vector `c` and `preimage[c]` the combination of unit vectors that produced it, so
    /// `M · preimage[c] == image[c]` holds throughout. The invariant
    /// `M · solution + rhs == target` is preserved by every step, so `rhs == 0` at the end
    /// means `solution` is a preimage of `target`.
    fn solve_artin_schreier(columns: &[u128; 128], target: u128) -> u128 {
        let mut image = *columns;
        let mut preimage: [u128; 128] = core::array::from_fn(|c| 1u128 << c);

        let mut rhs = target;
        let mut solution = 0u128;
        let mut consumed = 0u128;

        for bit in 0..128 {
            // Take any column not yet used as a pivot that still has this bit set.
            let Some(pivot) =
                (0..128).find(|&c| consumed >> c & 1 == 0 && image[c] >> bit & 1 == 1)
            else {
                continue;
            };
            consumed |= 1 << pivot;

            // Clear the bit everywhere else, so no later step can set it again.
            for c in 0..128 {
                if c != pivot && image[c] >> bit & 1 == 1 {
                    image[c] ^= image[pivot];
                    preimage[c] ^= preimage[pivot];
                }
            }
            if rhs >> bit & 1 == 1 {
                rhs ^= image[pivot];
                solution ^= preimage[pivot];
            }
        }

        assert_eq!(rhs, 0, "target is outside the image of x -> x^2 + x");

        // The kernel is `{0, 1}`, so exactly one of the two solutions has bit 0 clear.
        if solution & 1 == 1 {
            solution ^ 1
        } else {
            solution
        }
    }
}
